def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[+\-*/(),:=<>]"
    )
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "u-": 3,
        ":": 4,
    }

    def parse(formula):
        tokens = token_pattern.findall(formula)
        operands = []
        operators = []
        expecting_operand = True
        i = 0

        def reduce_operator():
            op = operators.pop()
            if op == "u-":
                operands.append(("neg", operands.pop()))
            else:
                right = operands.pop()
                left = operands.pop()
                if op == ":":
                    operands.append(("range", left[1], right[1]))
                else:
                    operands.append(("op", op, left, right))

        while i < len(tokens):
            token = tokens[i]

            if token.isdigit():
                operands.append(("number", int(token)))
                expecting_operand = False
            elif token[0].isalpha():
                if i + 1 < len(tokens) and tokens[i + 1] == "(":
                    operators.append(["(", token, 0])
                    i += 1
                    expecting_operand = True
                else:
                    operands.append(("ref", token))
                    expecting_operand = False
            elif token == "(":
                operators.append(["(", None, 0])
                expecting_operand = True
            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_operator()
                operators[-1][2] += 1
                expecting_operand = True
            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_operator()
                marker = operators.pop()
                if marker[1] is not None:
                    count = marker[2] + 1
                    args = operands[-count:]
                    del operands[-count:]
                    operands.append(("call", marker[1], args))
                expecting_operand = False
            else:
                op = "u-" if token == "-" and expecting_operand else token
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and (
                        precedence[operators[-1]] > precedence[op]
                        or (
                            precedence[operators[-1]] == precedence[op]
                            and op != "u-"
                        )
                    )
                ):
                    reduce_operator()
                operators.append(op)
                expecting_operand = True
            i += 1

        while operators:
            reduce_operator()
        return operands[0]

    values = {}
    active = set()

    def evaluate(start):
        tasks = [("cell", start)]
        results = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name in values:
                    results.append(values[name])
                elif name not in cells:
                    results.append(0)
                elif name in active:
                    results.append("#CYCLE!")
                else:
                    active.add(name)
                    content = cells[name]
                    tasks.append(("finish_cell", name))
                    if content.startswith("="):
                        tasks.append(("eval", parse(content[1:])))
                    else:
                        results.append(int(content))

            elif kind == "finish_cell":
                name = task[1]
                values[name] = results[-1]
                active.remove(name)

            elif kind == "eval":
                node = task[1]
                node_kind = node[0]

                if node_kind == "number":
                    results.append(node[1])
                elif node_kind == "ref":
                    tasks.append(("cell", node[1]))
                elif node_kind == "neg":
                    tasks.append(("neg",))
                    tasks.append(("eval", node[1]))
                elif node_kind == "op":
                    tasks.append(("left", node[1], node[3]))
                    tasks.append(("eval", node[2]))
                elif node_kind == "call":
                    function, args = node[1], node[2]
                    if function == "IF":
                        tasks.append(("if", args[1], args[2]))
                        tasks.append(("eval", args[0]))
                    else:
                        expanded = []
                        for arg in args:
                            if arg[0] != "range":
                                expanded.append(arg)
                                continue
                            first, second = arg[1], arg[2]
                            col1, col2 = ord(first[0]), ord(second[0])
                            row1, row2 = int(first[1:]), int(second[1:])
                            for row in range(min(row1, row2), max(row1, row2) + 1):
                                for col in range(min(col1, col2), max(col1, col2) + 1):
                                    name = chr(col) + str(row)
                                    if name in cells:
                                        expanded.append(("ref", name))
                        tasks.append(("function", function, expanded, 0, None))

            elif kind == "neg":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif kind == "left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    tasks.append(("right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "right":
                op, left = task[1], task[2]
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                elif op == "+":
                    results.append(left + right)
                elif op == "-":
                    results.append(left - right)
                elif op == "*":
                    results.append(left * right)
                elif op == "/":
                    if right == 0:
                        results.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        results.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    results.append(left == right)
                elif op == "<>":
                    results.append(left != right)
                elif op == "<":
                    results.append(left < right)
                elif op == "<=":
                    results.append(left <= right)
                elif op == ">":
                    results.append(left > right)
                else:
                    results.append(left >= right)

            elif kind == "if":
                condition = results.pop()
                if isinstance(condition, str):
                    results.append(condition)
                else:
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "function":
                function, args, index, aggregate = task[1:]
                if index == len(args):
                    results.append(0 if aggregate is None else aggregate)
                else:
                    tasks.append(("function_value", function, args, index, aggregate))
                    tasks.append(("eval", args[index]))

            elif kind == "function_value":
                function, args, index, aggregate = task[1:]
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                else:
                    if aggregate is None:
                        aggregate = value
                    elif function == "SUM":
                        aggregate += value
                    elif function == "MIN":
                        aggregate = min(aggregate, value)
                    else:
                        aggregate = max(aggregate, value)
                    tasks.append(("function", function, args, index + 1, aggregate))

        return results[-1]

    for name in cells:
        if name not in values:
            evaluate(name)

    return {name: values[name] for name in cells}
